     3	import hotel.rooms.Room;
     4	import java.math.BigDecimal;
     5	import java.time.DayOfWeek;
     6	import java.time.temporal.ChronoUnit;
     7	
     8	/**
     9	 * A rate plan: who can use it, how the stay is priced and what comes back when the guest cancels. A new
    10	 * plan is a new constant with its own rules.
    11	 */
    12	public enum RatePlan {
    13	    /** Full price; the guest gets everything back when cancelling a confirmed reservation. */
    14	    STANDARD {
    15	        @Override
    16	        Price price(Room room, NewReservation request, int nights, BigDecimal subtotal) {
    17	            return discounted(nights, subtotal, BigDecimal.ZERO);
    18	        }
    19	
    20	        @Override
    21	        BigDecimal refund(BigDecimal amountPaid) {
    22	            return amountPaid;
    23	        }
    24	    },
    25	    /** 15% off, but nothing comes back on cancellation. */
    26	    NON_REFUNDABLE {
    27	        @Override
    28	        Price price(Room room, NewReservation request, int nights, BigDecimal subtotal) {
    29	            return discounted(nights, subtotal, new BigDecimal("0.15"));
    30	        }
    31	
    32	        @Override
    33	        BigDecimal refund(BigDecimal amountPaid) {
    34	            return PriceCalculator.cents(BigDecimal.ZERO);
    35	        }
    36	    },
    37	    /** The discount agreed with the guest's company, who must inform its code; everything comes back on cancellation. */
    38	    CORPORATE {
    39	        @Override
    40	        void validate(NewReservation request) {
    41	            company(request);
    42	        }
    43	
    44	        @Override
    45	        Price price(Room room, NewReservation request, int nights, BigDecimal subtotal) {
    46	            return discounted(nights, subtotal, company(request).discount());
    47	        }
    48	
    49	        @Override
    50	        BigDecimal refund(BigDecimal amountPaid) {
    51	            return amountPaid;
    52	        }
    53	
    54	        private Company company(NewReservation request) {
    55	            return Company.withCode(request.companyCode())
    56	                    .orElseThrow(() -> new HotelException(
    57	                            ErrorCode.INVALID_REQUEST, "the corporate plan needs the code of a company with an agreement"));
    58	        }
    59	    },
    60	    /** Friday to Sunday, two nights, at a fixed price all year round; half comes back on cancellation. */
    61	    WEEKEND_PACKAGE {
    62	        @Override
    63	        void validate(NewReservation request) {
    64	            if (request.checkIn().getDayOfWeek() != DayOfWeek.FRIDAY
    65	                    || !request.checkOut().equals(request.checkIn().plusDays(2))) {
    66	                throw new HotelException(
    67	                        ErrorCode.INVALID_REQUEST, "the weekend package is from a Friday to the Sunday after it");
    68	            }
    69	        }
    70	
    71	        @Override
    72	        Price price(Room room, NewReservation request, int nights, BigDecimal subtotal) {
    73	            BigDecimal packagePrice = PriceCalculator.cents(switch (room.type()) {
    74	                case STANDARD -> new BigDecimal("520.00");
    75	                case DELUXE -> new BigDecimal("820.00");
    76	                case SUITE -> new BigDecimal("1200.00");
    77	            });
    78	            return discounted(nights, packagePrice, BigDecimal.ZERO);
    79	        }
    80	
    81	        @Override
    82	        BigDecimal refund(BigDecimal amountPaid) {
    83	            return PriceCalculator.cents(amountPaid.multiply(new BigDecimal("0.50")));
    84	        }
    85	    },
    86	    /** 7 nights or more, with 10% off; everything comes back on cancellation. */
    87	    LONG_STAY {
    88	        private static final int MINIMUM_NIGHTS = 7;
    89	
    90	        @Override
    91	        void validate(NewReservation request) {
    92	            if (ChronoUnit.DAYS.between(request.checkIn(), request.checkOut()) < MINIMUM_NIGHTS) {
    93	                throw new HotelException(
    94	                        ErrorCode.INVALID_REQUEST, "the long stay plan needs at least " + MINIMUM_NIGHTS + " nights");
    95	            }
    96	        }
    97	
    98	        @Override
    99	        Price price(Room room, NewReservation request, int nights, BigDecimal subtotal) {
   100	            return discounted(nights, subtotal, new BigDecimal("0.10"));
   101	        }
   102	
   103	        @Override
   104	        BigDecimal refund(BigDecimal amountPaid) {
   105	            return amountPaid;
   106	        }
   107	    };
   108	
   109	    /** Throws INVALID_REQUEST when the reservation cannot use this plan. */
   110	    void validate(NewReservation request) {
   111	    }
   112	
   113	    /** The price of the stay; {@code subtotal} is the sum of the nights at the room's rates, season included. */
   114	    abstract Price price(Room room, NewReservation request, int nights, BigDecimal subtotal);
   115	
   116	    /** What goes back to the guest who paid {@code amountPaid} and cancels. */
   117	    abstract BigDecimal refund(BigDecimal amountPaid);
   118	
   119	    static Price discounted(int nights, BigDecimal subtotal, BigDecimal discountRate) {
   120	        BigDecimal discount = PriceCalculator.cents(subtotal.multiply(discountRate));
   121	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
   122	    }
