     3	import hotel.rooms.Room;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.time.LocalDate;
     7	import java.time.Month;
     8	
     9	/**
    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    11	 * high-season nights; the rate plan then prices the stay from that sum. Money is rounded to cents
    12	 * (half-even) at every step.
    13	 */
    14	public final class PriceCalculator {
    15	
    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    17	
    18	    public Price calculate(Room room, NewReservation request) {
    19	        int nights = 0;
    20	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    21	        for (LocalDate night = request.checkIn(); night.isBefore(request.checkOut()); night = night.plusDays(1)) {
    22	            subtotal = subtotal.add(nightPrice(room, night));
    23	            nights++;
    24	        }
    25	        return request.ratePlan().price(room, request, nights, subtotal);
    26	    }
    27	
    28	    BigDecimal nightPrice(Room room, LocalDate night) {
    29	        BigDecimal nightlyRate = room.nightlyRate();
    30	        if (isHighSeason(night)) {
    31	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    32	        }
    33	        return cents(nightlyRate);
    34	    }
    35	
    36	    /** High season: from December 15 to the end of February, and the whole of July. */
    37	    static boolean isHighSeason(LocalDate date) {
    38	        Month month = date.getMonth();
    39	        return month == Month.JANUARY
    40	                || month == Month.FEBRUARY
    41	                || month == Month.JULY
    42	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    43	    }
    44	
    45	    static BigDecimal cents(BigDecimal value) {
    46	        return value.setScale(2, RoundingMode.HALF_EVEN);
    47	    }
    48	}
